// ── fetch handler ─────────────────────────────────────────────────────────────

async function handleFetch(request, env) {
  const RESEND_KEY = env.RESEND_KEY;
  if (request.method === "OPTIONS") {
    return new Response(null, { headers: {
      "Access-Control-Allow-Origin": "*",
      "Access-Control-Allow-Methods": "POST, OPTIONS",
      "Access-Control-Allow-Headers": "Content-Type",
    }});
  }

  if (request.method === "GET") {
    const u = new URL(request.url);

    // ?debug — reseller info + KV key count
    if (u.searchParams.has("debug")) {
      const bq = await apiGet({ action: "bouquet" });
      const ri = await apiGet({ action: "reseller_info" });
      const _kr = await env.TRIALS.get('__keys__') || '[]';
      const _ke = JSON.parse(_kr);
      return jsonRes({ bouquet: bq.text.slice(0,400), reseller: ri.text.slice(0,200), kv_keys: _ke.length });
    }



    // ?list-trials — returns all trial usernames stored in KV so you can
    //   identify and manually delete them in the activationpanel.ru dashboard
    if (u.searchParams.has("list-trials")) {
      const keysRaw = await env.TRIALS.get('__keys__') || '[]';
      const emails = JSON.parse(keysRaw);
      const now2 = Date.now();
      const rows = [];
      for (const em of emails) {
        try {
          const raw = await env.TRIALS.get(`trial:${em}`);
          if (!raw) continue;
          const t = JSON.parse(raw);
          rows.push({
            email: em,
            username: t.username || '',
            expired: now2 >= t.expiry,
            created_at: new Date(t.created_at || 0).toISOString(),
          });
        } catch (_) {}
      }
      rows.sort((a, b) => (a.expired === b.expired ? 0 : a.expired ? -1 : 1));
      return jsonRes({ total: rows.length, trials: rows });
    }

    return new Response("Maple Stream TV Trial Worker — OK", { status: 200 });
  }

  if (request.method !== "POST") return jsonRes({ success: false, error: "POST only" }, 405);

  let body;
  try { body = await request.json(); }
  catch { return jsonRes({ success: false, error: "Invalid JSON" }, 400); }

  const { name, email, country, device, whatsapp, notes } = body;
  if (!name || !email) return jsonRes({ success: false, error: "Name and email required" }, 400);

  let step = "bouquet";
  try {
    // 1. Try to create a new IPTV line via the panel API.
    //    If the panel is full (Not enough credits) AND DEMO_USERNAME/DEMO_PASSWORD
    //    are set as Worker secrets, fall back to shared demo credentials instead.
    step = "create_demo";
    let username = "", password = "";
    let usedSharedDemo = false;

    // 1a. Try panel API first
    let panelOk = false;
    try {
      // Get package ID
      const bqRes = await apiGet({ action: "bouquet" });
      let packId = "all";
      if (bqRes.text.trim().startsWith("[") || bqRes.text.trim().startsWith("{")) {
        const arr = JSON.parse(bqRes.text);
        const list = Array.isArray(arr) ? arr : Object.values(arr);
        const pkg = list.find(b => (b.name || "").trim().toLowerCase() === PACK_NAME.toLowerCase());
        if (pkg) packId = pkg.id;
      }
      const crRes = await apiGet({
        action: "new", type: "m3u", sub: "99", pack: packId,
        notes: `Trial / maplestreamtv.ca / ${email} | ${whatsapp || ""}`,
      });
      if (crRes.text.trim().startsWith("[") || crRes.text.trim().startsWith("{")) {
        const crData = JSON.parse(crRes.text);
        const item = Array.isArray(crData) ? crData[0] : crData;
        if (item && String(item.status) === "true") {
          const rawUrl = item.url || "";
          try {
            const pu = new URL(rawUrl);
            username = pu.searchParams.get("username") || "";
            password = pu.searchParams.get("password") || "";
          } catch {}
          panelOk = true;
        } else {
          throw new Error(`Panel: ${item?.message || JSON.stringify(item)}`);
        }
      } else {
        throw new Error(`Panel non-JSON: ${crRes.text.slice(0, 200)}`);
      }
    } catch (panelErr) {
      // 1b. Fallback: use shared demo credentials if configured
      const demoUser = env.DEMO_USERNAME;
      const demoPass = env.DEMO_PASSWORD;
      if (demoUser && demoPass) {
        username = demoUser;
        password = demoPass;
        usedSharedDemo = true;
        console.log(`[create_demo] Panel failed (${panelErr.message}) — using shared demo credentials`);
      } else {
        // No fallback configured — propagate the original panel error
        throw panelErr;
      }
    }

    // 2. Build M3U URL
    step = "extract";
    const m3uUrl = `${HOST}/get.php?username=${encodeURIComponent(username)}&password=${encodeURIComponent(password)}&type=m3u_plus&output=ts`;

    // 4. Store in KV FIRST (so trial is always recorded even if email fails)
    step = "kv_store";
    const expiry = Date.now() + 24 * 60 * 60 * 1000;
    const trialData = { name, email, whatsapp, site: 'maplestreamtv.ca', username, password, m3uUrl, expiry, reminder_sent: false, followup_sent: false, welcome_email_id: null, shared_demo: usedSharedDemo, created_at: Date.now() };
    await env.TRIALS.put(
      `trial:${email}`,
      JSON.stringify(trialData),
      { expirationTtl: 30 * 24 * 60 * 60 }
    );
    // Update __keys__ index (read op, not list op — keeps KV list quota safe)
    try {
      const _existingKeys = JSON.parse(await env.TRIALS.get('__keys__') || '[]');
      if (!_existingKeys.includes(email)) {
        _existingKeys.push(email);
        await env.TRIALS.put('__keys__', JSON.stringify(_existingKeys), { expirationTtl: 90 * 24 * 60 * 60 });
      }
    } catch(_) {}
    // Notify central KV reader
    const _kvBody = JSON.stringify({ name, email, whatsapp, site: 'maplestreamtv.ca', phone: whatsapp, created_at: Date.now() });
    const _kvPost = () => fetch('https://iptv-kv-reader.medmaar.workers.dev/add',
      { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: _kvBody });
    try { await _kvPost(); }
    catch(_) { try { await new Promise(r => setTimeout(r, 1500)); await _kvPost(); } catch(__) {} }

    // 5. Welcome email
    step = "email_client";
    const welcomeEmailId = await sendEmail(email, "Your Maple Stream TV Free Trial is Ready — 24H Access Activated ✓", welcomeEmail(name, username, password, m3uUrl), RESEND_KEY);
    // Update KV with Resend email ID so cron can thread reminder/follow-up replies
    if (welcomeEmailId) {
      trialData.welcome_email_id = welcomeEmailId;
      await env.TRIALS.put(`trial:${email}`, JSON.stringify(trialData), { expirationTtl: 30 * 24 * 60 * 60 });
    }

    // 6. Admin notification
    step = "email_admin";
    await sendEmail(ADMIN_EMAIL, `Automation / maplestreamtv.ca / trial / ${name} / ${email}`, adminEmail(name, email, country, device, whatsapp, notes, username, password, m3uUrl), RESEND_KEY);

    return jsonRes({ success: true });

  } catch (err) {
    console.error(`[step=${step}]`, err.message);
    return jsonRes({ success: false, error: `[${step}] ${err.message}` }, 500);
  }
}

// ── helpers ── panel line deletion ────────────────────────────────────────────

async function deletePanelLine(username) {
  if (!username) return;
  try {
    const qs = new URLSearchParams({ action: "delete_user", username, api_key: API_KEY });
    await fetch(`${API_BASE}?${qs}`);
  } catch (_) {}
}

// ── cron handler ──────────────────────────────────────────────────────────────

async function handleScheduled(env) {
  const RESEND_KEY = env.RESEND_KEY;
  const now = Date.now();
  const FOUR_HOURS = 4 * 60 * 60 * 1000;
  const _keysRaw = await env.TRIALS.get('__keys__') || '[]';
  const _keyEmails = JSON.parse(_keysRaw);
  const keys = _keyEmails.map(e => ({ name: `trial:${e}` }));
  console.log(`[cron] Checking ${keys.length} trials`);

  for (const { name: key } of keys) {
    let trial;
    try { const raw = await env.TRIALS.get(key); if (!raw) continue; trial = JSON.parse(raw); } catch { continue; }
    const { name, email, username, password, m3uUrl, expiry, reminder_sent, followup_sent, welcome_email_id } = trial;

    if (!reminder_sent && now >= expiry - FOUR_HOURS && now < expiry) {
      try {
        await sendEmail(email, "Your Maple Stream TV Free Trial is Ready — 24H Access Activated ✓", reminderEmail(name, username, password, m3uUrl), RESEND_KEY, welcome_email_id);
        trial.reminder_sent = true;
        await env.TRIALS.put(key, JSON.stringify(trial), { expirationTtl: 30 * 24 * 60 * 60 });
        console.log(`[cron] Reminder → ${email}`);
      } catch (e) { console.error(`[cron] Reminder failed ${email}:`, e.message); }
    }

    if (!followup_sent && now >= expiry) {
      try {
        await sendEmail(email, "Your Maple Stream TV Free Trial is Ready — 24H Access Activated ✓", followupEmail(name), RESEND_KEY, welcome_email_id);
        trial.followup_sent = true;
        await env.TRIALS.put(key, JSON.stringify(trial), { expirationTtl: 30 * 24 * 60 * 60 });
        console.log(`[cron] Follow-up → ${email}`);
      } catch (e) { console.error(`[cron] Follow-up failed ${email}:`, e.message); }
    }
  }
}

export default {
  async fetch(request, env) { return tkLogoResponse(request) || handleFetch(request, env); },
  async scheduled(event, env, ctx) { ctx.waitUntil(handleScheduled(env)); },
};
